{
  "IP": "neorv32_sysinfo",
  "Conceptual Assets": [
    {
      "Concept ID": "C1",
      "Concept Name": "Software-visible clock-frequency word",
      "Unit": "neorv32_sysinfo",
      "Information": "The software-visible clock-frequency word is held in the first system-information entry, which software and system integration depend on when reading the configured clock frequency. It is initialized from CLOCK_FREQUENCY and can be replaced by a bus write.",
      "Rubric": {
        "Confidentiality": "no",
        "Integrity": "yes",
        "Availability": "no",
        "Undermined Expected Behavior": "no"
      },
      "Rubric Reason": "The word is directly mutable by bus_req_i.data on the clocked write at line 95, so an unauthorized write can corrupt the system information returned to software; the value is returned through bus_rsp_o.data at line 168.",
      "Objectives At Risk": [
        "I"
      ],
      "Attack": "An attacker able to issue an unchecked write with bus_req_i.stb, bus_req_i.rw and the selected address can replace the clock-frequency word and cause software to receive incorrect system information.",
      "Enters Through": [
        "bus_req_i.data"
      ],
      "Leaves Through": [
        "bus_rsp_o.data"
      ],
      "Entry Lines": [
        95
      ],
      "Held Lines": [
        92,
        95
      ],
      "Exit Lines": [
        168
      ]
    }
  ],
  "Not Kept": [
    {
      "Candidate Name": "Static hardware capability and build configuration descriptors",
      "Candidate Unit": "neorv32_sysinfo",
      "Merged Into": "",
      "Why Not Kept": "The descriptors at lines 102-150 are derived only from build-time generics and constants, so no run-time element can modify them; the RTL also shows no confidentiality or availability requirement for them."
    },
    {
      "Candidate Name": "Bus access command and address",
      "Candidate Unit": "neorv32_sysinfo",
      "Merged Into": "",
      "Why Not Kept": "bus_req_i.stb, bus_req_i.rw and bus_req_i.addr only select, write and time accesses at lines 94 and 161-162, so the access-command and held-address rules do not treat them as information pieces of their own."
    },
    {
      "Candidate Name": "Bus response acknowledge",
      "Candidate Unit": "neorv32_sysinfo",
      "Merged Into": "",
      "Why Not Kept": "buf_ack only re-times the request strobe at line 160 and drives the response acknowledge at line 169, so it is a bus-handshake copy rather than an independent asset."
    },
    {
      "Candidate Name": "Buffered access address",
      "Candidate Unit": "neorv32_sysinfo",
      "Merged Into": "",
      "Why Not Kept": "buf_adr only copies the request address for selecting the returned system-information word at lines 162 and 168, so it is a held address used while the access is served."
    },
    {
      "Candidate Name": "Clock and reset timing",
      "Candidate Unit": "neorv32_sysinfo",
      "Merged Into": "",
      "Why Not Kept": "clk_i and rstn_i only time or reset the internal registers at lines 89-97 and 154-164, and the clock/reset rule excludes them as conceptual assets."
    }
  ],
  "Notes": []
}
